// ═══ INTERFACE HIERARCHY ═══
//
// Iterable<T>
//   └── Collection<T>
//         ├── List<T>        — ordered, indexed, duplicates OK
//         │     ├── ArrayList    (dynamic array, O(1) get, O(n) insert middle)
//         │     ├── LinkedList   (doubly-linked, O(1) add/remove ends, O(n) get)
//         │     └── Vector       (legacy synchronized ArrayList — don't use)
//         │
//         ├── Set<T>         — NO duplicates
//         │     ├── HashSet      (O(1) add/remove/contains, unordered)
//         │     ├── LinkedHashSet (O(1) ops + insertion order preserved)
//         │     └── TreeSet      (O(log n) ops, sorted by natural/comparator order)
//         │
//         └── Queue<T>       — FIFO processing
//               ├── LinkedList   (also implements Queue!)
//               ├── PriorityQueue (min-heap, smallest first)
//               └── Deque → ArrayDeque (double-ended, faster than Stack)
//
// Map<K,V>              — key-value pairs (SEPARATE hierarchy, not Collection!)
//   ├── HashMap           (O(1) get/put, unordered, allows null key)
//   ├── LinkedHashMap     (O(1) ops + insertion/access order)
//   ├── TreeMap           (O(log n) ops, sorted by key)
//   ├── Hashtable         (legacy synchronized — don't use)
//   └── ConcurrentHashMap (thread-safe, high concurrency)

// ═══ KEY INTERFACES ═══
List<String> accounts = new ArrayList<>();      // ordered, indexed
Set<String> uniqueIds = new HashSet<>();         // no duplicates
Queue<String> pending = new LinkedList<>();      // FIFO
Map<String, BigDecimal> balances = new HashMap<>(); // key→value lookup

// ═══ ALGORITHMS (Collections utility class) ═══
Collections.sort(accounts);                      // natural order sort
Collections.binarySearch(accounts, "SAV2001");   // must be sorted first!
Collections.shuffle(accounts);                   // random order
Collections.reverse(accounts);                   // reverse order
Collections.unmodifiableList(accounts);           // immutable wrapper
Collections.synchronizedMap(balances);            // thread-safe wrapper
Collections.frequency(accounts, "SAV2001");       // count occurrences

// ═══ JAVA 9+ FACTORY METHODS ═══
List<String> immutable = List.of("SAV2001", "CUR3001");     // immutable!
Set<String> immutableSet = Set.of("SAV2001", "CUR3001");
Map<String, Integer> immutableMap = Map.of("SAV2001", 50000);
```

