Collections.sort(accounts, Comparator.reverseOrder()); // reverse: [SAV2001, FD4001, CUR3001]
Collections.sort(accounts, String.CASE_INSENSITIVE_ORDER); // case-insensitive

// ═══ SEARCHING ═══
Collections.sort(accounts);  // MUST sort before binarySearch!
int idx = Collections.binarySearch(accounts, "FD4001");  // O(log n) — returns index
BigDecimal maxBal = Collections.max(balances, Comparator.naturalOrder());
BigDecimal minBal = Collections.min(balances);
int count = Collections.frequency(List.of("A", "B", "A", "A"), "A");  // 3

// ═══ REORDERING ═══
Collections.reverse(accounts);                     // reverses in-place
Collections.shuffle(accounts);                     // random order (lottery!)
Collections.swap(accounts, 0, 2);                  // swap positions
Collections.rotate(accounts, 1);                   // shifts right by 1

// ═══ IMMUTABLE WRAPPERS ═══
List<String> readOnly = Collections.unmodifiableList(accounts);
// readOnly.add("X") → UnsupportedOperationException!
// BUT: if 'accounts' is modified, readOnly REFLECTS the change (it's a view!)
// For TRUE immutable: List.copyOf(accounts) (Java 10) or List.of(...)

Map<String, BigDecimal> readOnlyMap = Collections.unmodifiableMap(balanceMap);
Set<String> readOnlySet = Collections.unmodifiableSet(accountSet);

// ═══ SYNCHRONIZED WRAPPERS ═══
List<String> syncList = Collections.synchronizedList(new ArrayList<>());
Map<String, String> syncMap = Collections.synchronizedMap(new HashMap<>());
// All methods synchronized — thread-safe but SLOW (one lock for everything)
// Better: ConcurrentHashMap, CopyOnWriteArrayList (finer-grained locking)

// IMPORTANT: iteration still needs external synchronization!
synchronized (syncList) {
    for (String s : syncList) { /* safe iteration */ }
}

// ═══ CHECKED WRAPPERS (type safety at runtime) ═══
List<String> checked = Collections.checkedList(new ArrayList<>(), String.class);
// checked.add(123) → ClassCastException at ADD time (not later at GET)!
// Useful for debugging heap pollution from raw types.

// ═══ FACTORY METHODS ═══
List<String> empty = Collections.emptyList();       // immutable empty
List<String> single = Collections.singletonList("SAV2001"); // immutable, one element
List<String> copies = Collections.nCopies(5, "DEFAULT");    // 5x "DEFAULT", immutable
