// ═══ PERFORMANCE COMPARISON ═══
//
// Operation              ArrayList       LinkedList
// get(index)             O(1) ✅         O(n) ❌ (traversal)
// add(end)               O(1) amortized  O(1)
// add(0, elem)           O(n) ❌ (shift)  O(1) ✅
// add(middle)            O(n)            O(n) (find) + O(1) (link)
// remove(index)          O(n) (shift)    O(n) (find) + O(1) (unlink)
// remove via Iterator    O(n) (shift)    O(1) ✅
// contains(elem)         O(n)            O(n)
// Memory per element     ~4 bytes (ref)  ~24 bytes (node: val+prev+next)
// Cache locality         EXCELLENT ✅     POOR ❌ (scattered in heap)

// ═══ ArrayList: dynamic array ═══
// Internal: Object[] elementData
// Default capacity: 10. Grows by 50% when full (10→15→22→33...)
// get(5) = elementData[5] — direct array access!

ArrayList<String> accounts = new ArrayList<>();
accounts.add("SAV2001");    // O(1) — append at end
accounts.get(0);             // O(1) — direct index access
accounts.add(0, "CUR3001"); // O(n) — shifts ALL elements right!
accounts.remove(0);          // O(n) — shifts ALL elements left!

// ═══ LinkedList: doubly-linked nodes ═══
// Internal: Node { E item; Node next; Node prev; }
// first → [A] ⇄ [B] ⇄ [C] ⇄ [D] ← last

LinkedList<String> trades = new LinkedList<>();
trades.addFirst("TRD-001"); // O(1) — update first pointer
trades.addLast("TRD-002");  // O(1) — update last pointer
trades.get(500);             // O(n) — traverse 500 nodes!
trades.removeFirst();        // O(1) — update first pointer

// ═══ WHY ArrayList WINS in practice ═══
// CPU cache: ArrayList's contiguous array = cache-friendly (prefetch works)
// LinkedList: nodes scattered across heap = cache misses = SLOW
// Even O(n) ArrayList shift is faster than O(n) LinkedList traversal
// because array shift = memcpy (CPU optimized) vs pointer chasing (cache misses)

// ═══ WHEN LinkedList IS better ═══
// 1. Used AS a Deque (addFirst/removeLast/addLast/removeFirst)
// 2. Frequent insert/remove during iteration (ListIterator.add/remove = O(1))
// 3. Never need random access by index
// In practice: ArrayDeque is better than LinkedList even as a Deque!
