package com.bank.listcompare;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ArrayVsLinkedTest {

    // ═══ ArrayList: fast random access ═══
    @Test
    void arrayList_fastGet() {
        List<String> accounts = new ArrayList<>();
        for (int i = 0; i < 10000; i++) accounts.add("ACC-" + i);

        long start = System.nanoTime();
        String mid = accounts.get(5000);  // O(1) — direct index!
        long arrayTime = System.nanoTime() - start;

        assertThat(mid).isEqualTo("ACC-5000");
        assertThat(arrayTime).isLessThan(1_000_000); // < 1ms
    }

    // ═══ LinkedList: slow random access ═══
    @Test
    void linkedList_slowGet() {
        LinkedList<String> accounts = new LinkedList<>();
        for (int i = 0; i < 10000; i++) accounts.add("ACC-" + i);

        String mid = accounts.get(5000);  // O(n) — traverse 5000 nodes!
        assertThat(mid).isEqualTo("ACC-5000");
        // Much slower than ArrayList.get(5000)
    }

    // ═══ LinkedList: fast addFirst ═══
    @Test
    void linkedList_fastAddFirst() {
        LinkedList<String> deque = new LinkedList<>();
        deque.addFirst("TRD-003");
        deque.addFirst("TRD-002");
        deque.addFirst("TRD-001");

        assertThat(deque).containsExactly("TRD-001", "TRD-002", "TRD-003");
        // addFirst = O(1) — just update head pointer
    }

    // ═══ ArrayList: slow addFirst (shifts all) ═══
    @Test
    void arrayList_slowAddFirst() {
        List<String> list = new ArrayList<>(List.of("B", "C", "D"));
        list.add(0, "A");  // O(n) — shifts B, C, D right!
        assertThat(list).containsExactly("A", "B", "C", "D");
    }

    // ═══ Performance benchmark: get() ═══
    @Test
    void benchmark_randomAccess() {
        int size = 50_000;
        ArrayList<Integer> arrayList = new ArrayList<>();
        LinkedList<Integer> linkedList = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            arrayList.add(i);
            linkedList.add(i);
        }

        // ArrayList get:
        long t1 = System.nanoTime();
        for (int i = 0; i < 1000; i++) arrayList.get(size / 2);
        long arrayMs = (System.nanoTime() - t1) / 1_000_000;

        // LinkedList get:
        long t2 = System.nanoTime();
        for (int i = 0; i < 1000; i++) linkedList.get(size / 2);
        long linkedMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("ArrayList.get: " + arrayMs + "ms, LinkedList.get: " + linkedMs + "ms");
        assertThat(arrayMs).isLessThanOrEqualTo(linkedMs);
        // ArrayList: ~0ms. LinkedList: ~50-200ms. Massive difference!
    }

    // ═══ Memory comparison ═══
    @Test
    void memoryDifference() {
        // ArrayList: Object[] + element references
        //   Per element: ~4 bytes (reference) + occasional resize overhead
        //   10K elements ≈ 40KB + array overhead
        //
        // LinkedList: Node objects (item + next + prev)
        //   Per node: ~24 bytes (object header + 3 references)
        //   10K elements ≈ 240KB — 6x MORE memory!
        assertThat(true).isTrue();
    }
}
