// ═══ INTERNAL STRUCTURE (simplified from OpenJDK source) ═══
public class ArrayList<E> {
    Object[] elementData;  // THE ARRAY — stores elements
    int size;              // number of actual elements (NOT capacity!)

    // Default constructor: lazy initialization (empty array until first add)
    public ArrayList() {
        this.elementData = {};  // empty! Becomes capacity 10 on first add.
    }

    // Capacity constructor: pre-allocate
    public ArrayList(int initialCapacity) {
        this.elementData = new Object[initialCapacity];
    }

    // add(E e): append at end
    public boolean add(E e) {
        ensureCapacity(size + 1);  // grow if needed
        elementData[size++] = e;   // place at end, increment size
        return true;
    }

    // GROWTH FORMULA:
    // newCapacity = oldCapacity + (oldCapacity >> 1)  // 1.5x
    // 10 → 15 → 22 → 33 → 49 → 73 → 109 → 163 → 244 → 366...
    // Then: Arrays.copyOf(elementData, newCapacity)
    //   → internally: System.arraycopy() — native memcpy, very fast!

    // get(int index): direct array access
    public E get(int index) {
        rangeCheck(index);                    // bounds check
        return (E) elementData[index];        // O(1)!
    }

    // add(int index, E e): insert at position → SHIFTS elements!
    public void add(int index, E e) {
        ensureCapacity(size + 1);
        System.arraycopy(elementData, index,
                         elementData, index + 1, size - index);  // shift right!
        elementData[index] = e;
        size++;
    }

    // remove(int index): SHIFTS elements left
    public E remove(int index) {
        E old = (E) elementData[index];
        System.arraycopy(elementData, index + 1,
                         elementData, index, size - index - 1);  // shift left!
        elementData[--size] = null;  // help GC
        return old;
    }
}

// ═══ GROWTH VISUALIZATION ═══
// add() calls:   1...10    11      12...15   16      17...22   23
// capacity:      10        15      15        22      22        33
// resize at:              add(11)           add(16)           add(23)
// Each resize: new array + copy ALL existing elements!

// ═══ INITIAL CAPACITY — avoid resizing ═══
// Loading 1,000,000 accounts:
List<String> bad = new ArrayList<>();           // resizes ~40 times!
List<String> good = new ArrayList<>(1_000_000); // ONE allocation, zero resizes!

// ═══ trimToSize — reclaim wasted memory ═══
ArrayList<String> list = new ArrayList<>(1000);
// Added only 50 elements → capacity 1000, size 50 → 950 slots wasted!
list.trimToSize();  // capacity shrinks to 50 — memory reclaimed!

// ═══ size vs capacity ═══
// size() = number of elements actually stored
// capacity = length of internal array (NOT accessible directly!)
// list.size() returns 50, but capacity might be 1000
