// ═══ INTERNAL STRUCTURE (simplified from OpenJDK) ═══
public class LinkedList<E> implements List<E>, Deque<E> {
    int size;
    Node<E> first;  // head pointer
    Node<E> last;   // tail pointer

    private static class Node<E> {
        E item;
        Node<E> next;
        Node<E> prev;

        Node(Node<E> prev, E element, Node<E> next) {
            this.item = element;
            this.prev = prev;
            this.next = next;
        }
    }

    // addFirst: O(1)
    public void addFirst(E e) {
        Node<E> f = first;
        Node<E> newNode = new Node<>(null, e, f);
        first = newNode;
        if (f == null) last = newNode;
        else f.prev = newNode;
        size++;
    }

    // get(index): O(n) — traverse!
    public E get(int index) {
        // Optimization: if index < size/2, traverse from head
        // else traverse from tail (saves half the traversal)
        Node<E> x;
        if (index < (size >> 1)) {
            x = first;
            for (int i = 0; i < index; i++) x = x.next;
        } else {
            x = last;
            for (int i = size - 1; i > index; i--) x = x.prev;
        }
        return x.item;
    }
}

// ═══ AS A DEQUE (double-ended queue) ═══
LinkedList<String> deque = new LinkedList<>();
deque.addFirst("A");     // O(1) — head insert
deque.addLast("B");      // O(1) — tail insert
deque.removeFirst();     // O(1) — head remove
deque.removeLast();      // O(1) — tail remove
deque.peekFirst();       // O(1) — peek head (no remove)
deque.peekLast();        // O(1) — peek tail

// ═══ LISTITERATOR: O(1) insert/remove AT POSITION ═══
LinkedList<String> list = new LinkedList<>(List.of("A", "B", "D"));
ListIterator<String> it = list.listIterator(2);  // positioned before "D"
it.add("C");  // O(1)! Just update prev/next pointers of surrounding nodes
// list = [A, B, C, D] — no array shifting!
// This is LinkedList's TRUE advantage over ArrayList.
```

