package com.bank.sublist;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class SubListGotchasTest {

    // ═══ subList is a VIEW — modifications write-through ═══
    @Test
    void subList_writesThrough() {
        List<String> accounts = new ArrayList<>(List.of("A", "B", "C", "D", "E"));
        List<String> sub = accounts.subList(1, 4);  // [B, C, D]

        sub.set(0, "B-MODIFIED");
        assertThat(accounts.get(1)).isEqualTo("B-MODIFIED");  // parent changed!

        sub.remove(0);  // removes "B-MODIFIED"
        assertThat(accounts).containsExactly("A", "C", "D", "E");  // parent shrank!
    }

    // ═══ Parent structural change → CME on sublist ═══
    @Test
    void parentChange_causesCME() {
        List<String> list = new ArrayList<>(List.of("A", "B", "C"));
        List<String> sub = list.subList(0, 2);  // [A, B]

        list.add("D");  // structural change to parent!

        assertThatThrownBy(() -> sub.get(0))
            .isInstanceOf(ConcurrentModificationException.class);
        // sublist INVALIDATED!
    }

    // ═══ Independent copy — safe from parent changes ═══
    @Test
    void independentCopy_safe() {
        List<String> original = new ArrayList<>(List.of("A", "B", "C", "D"));
        List<String> copy = new ArrayList<>(original.subList(1, 3));  // [B, C]

        original.add("E");       // modify parent
        original.set(1, "X");    // modify parent

        // copy is UNAFFECTED:
        assertThat(copy).containsExactly("B", "C");
    }

    // ═══ subList for efficient bulk clear ═══
    @Test
    void subList_bulkDelete() {
        List<String> trades = new ArrayList<>(List.of("T1", "T2", "T3", "T4", "T5"));
        trades.subList(1, 4).clear();  // removes T2, T3, T4
        assertThat(trades).containsExactly("T1", "T5");
        // More efficient than removing one by one!
    }

    // ═══ subList for pagination (safe copy) ═══
    @Test
    void pagination_safeCopy() {
        List<String> allTrades = new ArrayList<>();
        for (int i = 0; i < 100; i++) allTrades.add("TRD-" + i);

        int page = 2, pageSize = 10;
        int from = page * pageSize;  // 20
        int to = Math.min(from + pageSize, allTrades.size());  // 30

        // SAFE: independent copy for API response
        List<String> page2 = new ArrayList<>(allTrades.subList(from, to));
        assertThat(page2).hasSize(10);
        assertThat(page2.get(0)).isEqualTo("TRD-20");

        // Parent can change — page2 is unaffected:
        allTrades.add("TRD-100");
        assertThat(page2).hasSize(10);  // still 10!
    }

    // ═══ subList of subList — chained views ═══
    @Test
    void nestedSubList() {
        List<String> list = new ArrayList<>(List.of("A", "B", "C", "D", "E"));
        List<String> sub1 = list.subList(1, 4);     // [B, C, D]
        List<String> sub2 = sub1.subList(0, 2);     // [B, C]

        sub2.set(0, "Z");
        assertThat(list).containsExactly("A", "Z", "C", "D", "E");
        // Nested sublists ALL write-through to the root list!
    }
