// ═══ ArrayDeque INTERNALS ═══
// Backed by: Object[] (circular array)
// Two pointers: head (front) and tail (back)
// Wraps around: when head reaches 0, it wraps to array.length-1
// Growth: doubles (2x) when full
// NO null elements allowed (null is used as internal sentinel)

// ═══ AS A STACK (LIFO) — replaces Stack class ═══
Deque<String> stack = new ArrayDeque<>();
stack.push("TXN-001");     // pushes to HEAD → O(1)
stack.push("TXN-002");
String top = stack.peek();  // "TXN-002" — view top without removing
String popped = stack.pop();// "TXN-002" — LIFO: last in, first out!

// ═══ AS A QUEUE (FIFO) — replaces LinkedList as Queue ═══
Deque<String> queue = new ArrayDeque<>();
queue.offer("TXN-001");     // adds to TAIL → O(1)
queue.offer("TXN-002");
queue.offer("TXN-003");
String first = queue.poll(); // "TXN-001" — FIFO: first in, first out!

// ═══ AS A DEQUE (both ends) ═══
Deque<String> deque = new ArrayDeque<>();
deque.addFirst("B");
deque.addFirst("A");
deque.addLast("C");
// [A, B, C]
deque.removeFirst();  // "A"
deque.removeLast();   // "C"

// ═══ COMPARISON TABLE ═══
// Feature              ArrayDeque         LinkedList         Stack
// Backing structure    circular array     doubly-linked      array (Vector)
// Cache locality       EXCELLENT ✅        POOR ❌            OK
// Synchronized         NO (fast)          NO                 YES (slow!)
// Null elements        NOT allowed        allowed            allowed
// Random access        NO (Deque only)    YES (but O(n))     YES (violates stack!)
// Memory per element   ~8 bytes           ~40 bytes          ~8 bytes + sync
// Growth               2x                 per-node alloc     2x
// Recommendation       ✅ USE THIS         only if need List  ❌ LEGACY
