package com.bank.deque;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ArrayDequeTest {

    // ═══ Stack (LIFO) ═══
    @Test
    void asStack_lifo() {
        Deque<String> stack = new ArrayDeque<>();
        stack.push("undo-1");
        stack.push("undo-2");
        stack.push("undo-3");

        assertThat(stack.peek()).isEqualTo("undo-3");  // top
        assertThat(stack.pop()).isEqualTo("undo-3");   // LIFO!
        assertThat(stack.pop()).isEqualTo("undo-2");
        assertThat(stack.pop()).isEqualTo("undo-1");
        assertThat(stack).isEmpty();
    }

    // ═══ Queue (FIFO) ═══
    @Test
    void asQueue_fifo() {
        Deque<String> queue = new ArrayDeque<>();
        queue.offer("TXN-001");
        queue.offer("TXN-002");
        queue.offer("TXN-003");

        assertThat(queue.poll()).isEqualTo("TXN-001");  // FIFO!
        assertThat(queue.poll()).isEqualTo("TXN-002");
        assertThat(queue.poll()).isEqualTo("TXN-003");
        assertThat(queue.poll()).isNull();  // empty → null (no exception!)
    }

    // ═══ Deque (both ends) ═══
    @Test
    void asDeque_bothEnds() {
        Deque<String> deque = new ArrayDeque<>();
        deque.addFirst("B");
        deque.addFirst("A");    // [A, B]
        deque.addLast("C");     // [A, B, C]

        assertThat(deque.peekFirst()).isEqualTo("A");
        assertThat(deque.peekLast()).isEqualTo("C");
        assertThat(deque.removeFirst()).isEqualTo("A");
        assertThat(deque.removeLast()).isEqualTo("C");
        assertThat(deque).containsExactly("B");
    }

    // ═══ No null allowed ═══
    @Test
    void noNullAllowed() {
        Deque<String> deque = new ArrayDeque<>();
        assertThatThrownBy(() -> deque.push(null))
            .isInstanceOf(NullPointerException.class);
        // LinkedList allows null. ArrayDeque does NOT.
    }

    // ═══ Performance: ArrayDeque vs LinkedList as Queue ═══
    @Test
    void performance_arrayDequeVsLinkedList() {
        int n = 500_000;

        // ArrayDeque:
        long t1 = System.nanoTime();
        Deque<Integer> ad = new ArrayDeque<>();
        for (int i = 0; i < n; i++) ad.offer(i);
        while (!ad.isEmpty()) ad.poll();
        long adMs = (System.nanoTime() - t1) / 1_000_000;

        // LinkedList:
        long t2 = System.nanoTime();
        Deque<Integer> ll = new LinkedList<>();
        for (int i = 0; i < n; i++) ll.offer(i);
        while (!ll.isEmpty()) ll.poll();
        long llMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("ArrayDeque: " + adMs + "ms, LinkedList: " + llMs + "ms");
        // ArrayDeque typically 2-3x faster!
    }

    // ═══ Legacy Stack — DON'T use ═══
    @Test
    void legacyStack_whyBad() {
        Stack<String> stack = new Stack<>();
        stack.push("A");
        stack.push("B");
        stack.push("C");

        // BAD: Stack allows random access (violates LIFO abstraction!)
        String middle = stack.get(1);  // "B" — shouldn't be possible in a stack!
        assertThat(middle).isEqualTo("B");

        // BAD: Stack extends Vector — all methods synchronized!
        // Even single-threaded: lock overhead on every push/pop.
    }
}
