class TxnProcessor {
  // circular array: head/tail indices, resize by doubling
  Deque<Transaction> queue = new ArrayDeque<>();
  Deque<Action>      undo  = new ArrayDeque<>();

  void enqueue(Transaction t){ queue.offerLast(t); } // tail
  Transaction next(){ return queue.pollFirst(); }    // head

  void doAction(Action a){ a.apply(); undo.push(a); } // top
  void undoLast(){ if(!undo.isEmpty()) undo.pop().revert(); }

  // internals: Object[] elements; int head, tail;
  //   wrap: index = (i+1) & (len-1)   (power-of-2 size)
  //   null NOT allowed (null = empty-slot marker)
  //   does NOT implement List (no get(index))
}
