package com.bank.syncmap;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class SynchronizedMapTest {

    // ═══ synchronizedMap: basic thread safety ═══
    @Test
    void synchronizedMap_basicOps() {
        Map<String, BigDecimal> map = Collections.synchronizedMap(new HashMap<>());
        map.put("SAV2001", new BigDecimal("75000"));
        map.put("CUR3001", new BigDecimal("120000"));

        assertThat(map.get("SAV2001")).isEqualByComparingTo("75000");
        assertThat(map).hasSize(2);
    }

    // ═══ Iteration WITHOUT sync — risky! ═══
    @Test
    void iteration_mustSynchronize() {
        Map<String, String> map = Collections.synchronizedMap(new HashMap<>());
        map.put("A", "1");
        map.put("B", "2");

        // SAFE iteration:
        List<String> keys = new ArrayList<>();
        synchronized (map) {
            for (String key : map.keySet()) {
                keys.add(key);
            }
        }
        assertThat(keys).containsExactlyInAnyOrder("A", "B");
    }

    // ═══ ConcurrentHashMap: no sync needed for iteration ═══
    @Test
    void concurrentHashMap_safeIteration() {
        ConcurrentHashMap<String, String> chm = new ConcurrentHashMap<>();
        chm.put("A", "1");
        chm.put("B", "2");

        // No synchronized block needed!
        List<String> keys = new ArrayList<>();
        for (String key : chm.keySet()) {
            keys.add(key);  // weakly consistent — safe!
        }
        assertThat(keys).containsExactlyInAnyOrder("A", "B");
    }

    // ═══ Compound operation: race condition in synchronizedMap ═══
    @Test
    void compoundOp_raceCondition() {
        Map<String, Integer> syncMap = Collections.synchronizedMap(new HashMap<>());

        // This is NOT atomic in synchronizedMap:
        // if (!syncMap.containsKey("key")) syncMap.put("key", 1);
        // Two threads can both see containsKey=false → both put!

        // ConcurrentHashMap: atomic!
        ConcurrentHashMap<String, Integer> chm = new ConcurrentHashMap<>();
        chm.computeIfAbsent("key", k -> 1);  // atomic!
        chm.computeIfAbsent("key", k -> 2);  // key exists → no change!
        assertThat(chm.get("key")).isEqualTo(1);
    }

    // ═══ Performance comparison ═══
    @Test
    void performance() {
        int n = 100_000;

        Map<Integer, Integer> syncMap = Collections.synchronizedMap(new HashMap<>());
        long t1 = System.nanoTime();
        for (int i = 0; i < n; i++) syncMap.put(i, i);
        synchronized (syncMap) { for (var e : syncMap.entrySet()) { /* iterate */ } }
        long syncMs = (System.nanoTime() - t1) / 1_000_000;

        ConcurrentHashMap<Integer, Integer> chm = new ConcurrentHashMap<>();
        long t2 = System.nanoTime();
        for (int i = 0; i < n; i++) chm.put(i, i);
        for (var e : chm.entrySet()) { /* iterate — no sync needed! */ }
        long chmMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("synchronizedMap: " + syncMs + "ms, ConcurrentHashMap: " + chmMs + "ms");
    }
}
