// ═══ VALUE OVERWRITE ═══
Map<String, BigDecimal> balances = new HashMap<>();
BigDecimal old1 = balances.put("SAV2001", new BigDecimal("50000"));
// old1 = null (key didn't exist before)

BigDecimal old2 = balances.put("SAV2001", new BigDecimal("75000"));
// old2 = 50000 (OLD value returned!)
// Map now: {"SAV2001" → 75000} — value REPLACED!
// Size is still 1 — not 2!

// ═══ putIfAbsent — insert ONLY if key not present ═══
balances.putIfAbsent("SAV2001", new BigDecimal("99999"));
// SAV2001 already exists → NOT replaced! Returns existing value 75000.
balances.putIfAbsent("CUR3001", new BigDecimal("120000"));
// CUR3001 doesn't exist → inserted! Returns null.

// ═══ KEY OBJECT IS NOT REPLACED ═══
String key1 = new String("SAV2001");
String key2 = new String("SAV2001");  // different object, same value
Map<String, String> map = new HashMap<>();
map.put(key1, "first");
map.put(key2, "second");  // key1.equals(key2) → value replaced!
// The key in the map is STILL key1 (original), not key2!
// Only value changed. Size = 1.

// ═══ merge — combine old and new values ═══
Map<String, Integer> txnCounts = new HashMap<>();
txnCounts.put("SAV2001", 5);
txnCounts.merge("SAV2001", 3, Integer::sum);  // 5 + 3 = 8
// merge: if key exists → apply function(oldValue, newValue)
// if key absent → just put newValue
