// ─── File: src/test/java/com/bank/duplicate/DuplicateKeyTest.java ───
package com.bank.duplicate;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class DuplicateKeyTest {

    @Test
    void put_overwritesAndReturnsOldValue() {
        Map<String, BigDecimal> map = new HashMap<>();
        BigDecimal old1 = map.put("SAV2001", new BigDecimal("50000"));
        assertThat(old1).isNull();  // first insert → no old value

        BigDecimal old2 = map.put("SAV2001", new BigDecimal("75000"));
        assertThat(old2).isEqualByComparingTo("50000");  // OLD value returned!
        assertThat(map.get("SAV2001")).isEqualByComparingTo("75000");  // new value stored
        assertThat(map).hasSize(1);  // still 1! Not 2!
    }

    @Test
    void putIfAbsent_doesNotOverwrite() {
        Map<String, String> map = new HashMap<>();
        map.put("SAV2001", "Rajesh");

        String result = map.putIfAbsent("SAV2001", "Priya");
        assertThat(result).isEqualTo("Rajesh");  // existing value returned
        assertThat(map.get("SAV2001")).isEqualTo("Rajesh");  // NOT replaced!

        String result2 = map.putIfAbsent("CUR3001", "Priya");
        assertThat(result2).isNull();  // newly inserted → null
        assertThat(map.get("CUR3001")).isEqualTo("Priya");
    }

    @Test
    void merge_combinesValues() {
        Map<String, Integer> counts = new HashMap<>();
        counts.put("SAV2001", 5);

        counts.merge("SAV2001", 3, Integer::sum);  // 5 + 3 = 8
        assertThat(counts.get("SAV2001")).isEqualTo(8);

        counts.merge("CUR3001", 10, Integer::sum);  // absent → just put 10
        assertThat(counts.get("CUR3001")).isEqualTo(10);
    }

    @Test
    void keyObjectNotReplaced() {
        String key1 = new String("SAV2001");
        String key2 = new String("SAV2001");
        assertThat(key1).isNotSameAs(key2);  // different objects!
        assertThat(key1).isEqualTo(key2);     // but equals!

        Map<String, String> map = new HashMap<>();
        map.put(key1, "first");
        map.put(key2, "second");

        assertThat(map).hasSize(1);  // one entry!
        // The key stored is key1 (original), not key2
        for (String key : map.keySet()) {
            assertThat(key).isSameAs(key1);  // original key object!
        }
    }
}
