// ═══ THE PROBLEM ═══
class Account {
    String id;
    Account(String id) { this.id = id; }

    @Override public int hashCode() { return id.hashCode(); }
    @Override public boolean equals(Object o) {
        return o instanceof Account a && a.id.equals(this.id);
    }
}

Map<Account, String> map = new HashMap<>();
Account key = new Account("SAV2001");
map.put(key, "Rajesh");
// Entry stored in bucket = hash("SAV2001") & (capacity - 1) = bucket #7

// MUTATE the key after insertion!
key.id = "CUR3001";
// key.hashCode() NOW returns hash("CUR3001") → bucket #12

map.get(key);           // null! Looks in bucket #12 → not there!
map.containsKey(key);   // false! Same problem.
map.get(new Account("SAV2001")); // null! Bucket #7 has the entry,
                        // but equals("SAV2001") fails because key.id is now "CUR3001"!
map.get(new Account("CUR3001")); // null! Bucket #12 → no entry there!

// The entry EXISTS in bucket #7 but is UNREACHABLE by any get/remove!
map.size();  // 1 — entry still counted! Memory leak!

// ═══ THE FIX: use immutable keys ═══
// String:  immutable ✅
// Integer: immutable ✅
// Enum:    immutable ✅
// Record:  immutable ✅ (if all components are immutable)
// Custom class: make fields final, no setters, defensive copies ✅
```

