// ─── File: src/test/java/com/bank/mutablekey/MutableKeyTest.java ───
package com.bank.mutablekey;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class MutableKeyTest {

    // Mutable key class
    static class MutableAccount {
        String id;
        MutableAccount(String id) { this.id = id; }
        @Override public int hashCode() { return id.hashCode(); }
        @Override public boolean equals(Object o) {
            return o instanceof MutableAccount a && a.id.equals(this.id);
        }
    }

    // Immutable key (record)
    record ImmutableAccount(String id) {}

    // ═══ MUTABLE KEY: entry lost after mutation ═══
    @Test
    void mutableKey_entryLost() {
        Map<MutableAccount, String> map = new HashMap<>();
        MutableAccount key = new MutableAccount("SAV2001");
        map.put(key, "Rajesh");

        assertThat(map.get(key)).isEqualTo("Rajesh");  // works BEFORE mutation

        // MUTATE the key!
        key.id = "CUR3001";

        // Entry is LOST:
        assertThat(map.get(key)).isNull();                        // null!
        assertThat(map.get(new MutableAccount("SAV2001"))).isNull(); // null!
        assertThat(map.get(new MutableAccount("CUR3001"))).isNull(); // null!
        assertThat(map.containsKey(key)).isFalse();               // false!

        // BUT entry still exists:
        assertThat(map).hasSize(1);          // size is 1!
        assertThat(map.isEmpty()).isFalse();  // not empty!
        // Entry is STUCK in old bucket — unreachable! Memory leak!
    }

    // ═══ IMMUTABLE KEY: always works ═══
    @Test
    void immutableKey_alwaysWorks() {
        Map<ImmutableAccount, String> map = new HashMap<>();
        ImmutableAccount key = new ImmutableAccount("SAV2001");
        map.put(key, "Rajesh");

        // key.id = "CUR3001";  → COMPILE ERROR! Record fields are final!
        assertThat(map.get(key)).isEqualTo("Rajesh");
        assertThat(map.get(new ImmutableAccount("SAV2001"))).isEqualTo("Rajesh");
    }

    // ═══ String key: always safe ═══
    @Test
    void stringKey_alwaysSafe() {
        Map<String, String> map = new HashMap<>();
        String key = "SAV2001";
        map.put(key, "Rajesh");

        // Strings are immutable — hashCode NEVER changes!
        assertThat(map.get("SAV2001")).isEqualTo("Rajesh");
        assertThat(map.get(key)).isEqualTo("Rajesh");
    }

    // ═══ Show entry exists but unreachable ═══
    @Test
    void entryExistsButUnreachable() {
        Map<MutableAccount, String> map = new HashMap<>();
        MutableAccount key = new MutableAccount("SAV2001");
        map.put(key, "Rajesh");
        key.id = "CUR3001";  // mutate!

        // Iterate: entry IS there!
        List<String> values = new ArrayList<>();
        for (var entry : map.entrySet()) {
            values.add(entry.getValue());
        }
        assertThat(values).containsExactly("Rajesh");  // found via iteration!
        // But get/containsKey/remove can NEVER find it by key!
    }
}
