// ═══ JAVA 8+ ConcurrentHashMap INTERNALS ═══

// Internal: volatile Node<K,V>[] table (same structure as HashMap)
// Node: hash, key, value (volatile!), next

// ═══ READ: ZERO locks! ═══
public V get(Object key) {
    int hash = spread(key.hashCode());
    Node<K,V>[] tab = table;  // volatile read of table reference
    Node<K,V> e = tabAt(tab, (tab.length - 1) & hash);  // volatile read of bucket
    // Walk chain using volatile next pointers — NO lock!
    while (e != null) {
        if (e.hash == hash && key.equals(e.key)) return e.val;  // val is volatile!
        e = e.next;
    }
    return null;
    // 100% lock-free! Multiple threads read simultaneously!
}

// ═══ WRITE: CAS for empty bucket, synchronized for non-empty ═══
public V put(K key, V value) {
    int hash = spread(key.hashCode());
    for (Node<K,V>[] tab = table;;) {
        Node<K,V> f = tabAt(tab, i = (tab.length - 1) & hash);

        if (f == null) {
            // Empty bucket → CAS (Compare-And-Swap) — no lock!
            if (casTabAt(tab, i, null, new Node<>(hash, key, value)))
                break;  // success! No lock needed!
            // CAS failed → another thread beat us → retry loop
        } else {
            // Non-empty bucket → synchronized on FIRST NODE only!
            synchronized (f) {
                // Walk chain: if key exists → replace
                // If not → append to end
                // If chain ≥ 8 → treeify
            }
            // ONLY this bucket locked! All other buckets accessible!
        }
    }
    addCount(1L);  // check if resize needed
}

// ═══ CONCURRENT RESIZE (transfer) ═══
// When table needs to grow:
// 1. New table (2x) allocated
// 2. transferIndex starts at old table's length
// 3. MULTIPLE threads help migrate buckets:
//    Each thread claims a STRIDE of buckets (min 16)
//    Thread claims: transferIndex -= stride (CAS)
//    Migrates those buckets to new table
//    Other threads claim other strides simultaneously!
// Result: resize is DISTRIBUTED — N threads = N times faster resize!

// ═══ JAVA 7 vs JAVA 8 COMPARISON ═══
// Feature            Java 7                    Java 8+
// Structure          Segment[] (16 segments)   Node[] (flat table)
// Read lock          Segment read lock         NONE (volatile)
// Write lock         Segment lock              CAS or sync(bucket)
// Granularity        per-segment (1/16)        per-bucket (1/N)
// Resize             single-threaded           multi-threaded!
// Treeify            no (linked list only)     yes (threshold 8)
// Null key/value     NOT allowed               NOT allowed
