// ═══ ACTUAL OpenJDK SOURCE (simplified) ═══
public class HashSet<E> implements Set<E> {
    private transient HashMap<E, Object> map;
    private static final Object PRESENT = new Object();  // dummy value!

    public HashSet() {
        map = new HashMap<>();
    }

    public HashSet(int initialCapacity) {
        map = new HashMap<>(initialCapacity);
    }

    public boolean add(E e) {
        return map.put(e, PRESENT) == null;
        // put returns null → key was NEW → add returns true
        // put returns PRESENT → key EXISTED → add returns false (duplicate!)
    }

    public boolean contains(Object o) {
        return map.containsKey(o);  // just delegate!
    }

    public boolean remove(Object o) {
        return map.remove(o) == PRESENT;  // just delegate!
    }

    public int size() {
        return map.size();  // just delegate!
    }

    public Iterator<E> iterator() {
        return map.keySet().iterator();  // iterate over KEYS!
    }
}

// ═══ CONSEQUENCES ═══
// 1. HashSet requires proper hashCode() + equals() on elements
//    (because elements are HashMap KEYS)
// 2. Default capacity: 16, load factor: 0.75 (from HashMap)
// 3. Treeify at 8 collisions (from HashMap, Java 8+)
// 4. One null element allowed (HashMap allows one null KEY)
// 5. Unordered (HashMap doesn't maintain insertion order)
// 6. For insertion order: LinkedHashSet (uses LinkedHashMap internally)
// 7. For sorted order: TreeSet (uses TreeMap internally)

// ═══ MEMORY ═══
// Each element stored as: HashMap.Node(hash, key=element, value=PRESENT, next)
// Overhead per element: ~32-48 bytes (Node object + references)
// The PRESENT object: created ONCE, shared by ALL entries (singleton)
