// treeMap.put(null, "value");      // ❌ NullPointerException!
// WHY? TreeMap.put() calls: key.compareTo(existingKey) or comparator.compare(key, existing)
// null.compareTo() → NPE! No way to determine sort position of null.

treeMap.put("SAV2001", null);       // ✅ null VALUE is fine (values not compared)

// ═══ TreeMap with Comparator handling null ═══
// You CAN make TreeMap accept null keys with a custom Comparator:
TreeMap<String, String> nullSafe = new TreeMap<>(Comparator.nullsFirst(Comparator.naturalOrder()));
nullSafe.put(null, "no-key");       // ✅ works! null sorts first.
nullSafe.put("SAV2001", "Rajesh");
// Order: null → SAV2001

// ═══ SUMMARY TABLE ═══
// Map Type          Null Key    Null Value
// HashMap           1 allowed   multiple allowed
// LinkedHashMap     1 allowed   multiple allowed
// TreeMap           ❌ NPE       multiple allowed
// Hashtable         ❌ NPE       ❌ NPE
