        map.put("SAV2001", "Rajesh");
        map.put("CUR3001", "Priya");

        assertThat(new ArrayList<>(map.keySet()))
            .containsExactly(null, "CUR3001", "SAV2001");  // null first!
    }

    @Test
    void concurrentHashMap_rejectsBothNull() {
        ConcurrentHashMap<String, String> map = new ConcurrentHashMap<>();
        assertThatThrownBy(() -> map.put(null, "v")).isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> map.put("k", null)).isInstanceOf(NullPointerException.class);
    }

    @Test
    void hashtable_rejectsBothNull() {
        Hashtable<String, String> map = new Hashtable<>();
        assertThatThrownBy(() -> map.put(null, "v")).isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> map.put("k", null)).isInstanceOf(NullPointerException.class);
    }
