// ═══ COMPARABLE: natural ordering IN the class ═══
public class Trade implements Comparable<Trade> {
    String tradeId;
    BigDecimal amount;
    LocalDate tradeDate;

    @Override
    public int compareTo(Trade other) {
        return this.tradeId.compareTo(other.tradeId);  // sort by tradeId
    }
    // This is THE natural order. ONE ordering. Baked in.
}

// Usage:
List<Trade> trades = ...;
Collections.sort(trades);            // uses compareTo() — natural order
TreeSet<Trade> sorted = new TreeSet<>(trades); // uses compareTo()

// ═══ COMPARATOR: external ordering OUTSIDE the class ═══
// Sort by amount:
Comparator<Trade> byAmount = Comparator.comparing(Trade::getAmount);
// Sort by date:
Comparator<Trade> byDate = Comparator.comparing(Trade::getTradeDate);
// Sort by amount descending, then by date:
Comparator<Trade> complex = Comparator.comparing(Trade::getAmount).reversed()
    .thenComparing(Trade::getTradeDate);

// Usage:
Collections.sort(trades, byAmount);               // external order
trades.sort(byDate);                               // List.sort
TreeSet<Trade> byAmountSet = new TreeSet<>(byAmount); // TreeSet with Comparator
trades.stream().sorted(complex).toList();           // stream sorting

// ═══ COMPARATOR UTILITY METHODS (Java 8+) ═══
Comparator.comparing(Trade::getAmount)              // by field
Comparator.comparing(Trade::getAmount).reversed()   // descending
Comparator.comparing(Trade::getName, String.CASE_INSENSITIVE_ORDER)  // custom
Comparator.comparingInt(Trade::getPriority)          // primitive (no boxing)
Comparator.comparingDouble(Trade::getPrice)
comp1.thenComparing(Trade::getDate)                  // secondary sort
Comparator.nullsFirst(Comparator.naturalOrder())     // null handling
Comparator.naturalOrder()                             // for Comparable types
Comparator.reverseOrder()                             // reverse natural

// ═══ COMPARABLE CONTRACT ═══
// compareTo returns:
//   negative → this < other
//   zero     → this == other
//   positive → this > other
// MUST be consistent with equals(): if compareTo() == 0, then equals() should be true
// (TreeSet uses compareTo for equality — not equals()!)

// ═══ GOTCHA: TreeSet uses compareTo, not equals! ═══
TreeSet<String> set = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
set.add("abc");
set.add("ABC");
// set.size() == 1! compareTo("abc","ABC") == 0 → treated as duplicate!
// Even though "abc".equals("ABC") == false!
