import static org.assertj.core.api.Assertions.*;

class ComparableVsComparatorTest {

    // Trade with natural ordering by tradeId
    record Trade(String tradeId, BigDecimal amount, String counterparty)
        implements Comparable<Trade> {

        @Override
        public int compareTo(Trade other) {
            return this.tradeId.compareTo(other.tradeId);  // natural order!
        }
    }

    static final Trade T1 = new Trade("TRD-003", new BigDecimal("500000"), "HDFC");
    static final Trade T2 = new Trade("TRD-001", new BigDecimal("100000"), "ICICI");
    static final Trade T3 = new Trade("TRD-002", new BigDecimal("750000"), "SBI");

    // ═══ Comparable: natural order ═══
    @Test
    void comparable_naturalOrder() {
        List<Trade> trades = new ArrayList<>(List.of(T1, T2, T3));
        Collections.sort(trades);  // uses compareTo → by tradeId
        assertThat(trades).containsExactly(T2, T3, T1);  // TRD-001, TRD-002, TRD-003
    }

    // ═══ Comparator: sort by amount ═══
    @Test
    void comparator_byAmount() {
        List<Trade> trades = new ArrayList<>(List.of(T1, T2, T3));
        trades.sort(Comparator.comparing(Trade::amount));
        assertThat(trades).containsExactly(T2, T1, T3);  // 100K, 500K, 750K
    }

    // ═══ Comparator: sort by amount descending ═══
    @Test
    void comparator_byAmountDescending() {
        List<Trade> trades = new ArrayList<>(List.of(T1, T2, T3));
        trades.sort(Comparator.comparing(Trade::amount).reversed());
        assertThat(trades).containsExactly(T3, T1, T2);  // 750K, 500K, 100K
    }

    // ═══ Comparator: multi-level sort ═══
    @Test
    void comparator_multiLevel() {
        Trade t4 = new Trade("TRD-004", new BigDecimal("500000"), "AXIS");
        List<Trade> trades = new ArrayList<>(List.of(T1, T2, T3, t4));

        // Sort by amount, then by counterparty (for same amount)
        trades.sort(Comparator.comparing(Trade::amount)
            .thenComparing(Trade::counterparty));

        assertThat(trades.get(0)).isEqualTo(T2);          // 100K
        assertThat(trades.get(1).counterparty()).isEqualTo("AXIS");  // 500K, AXIS
        assertThat(trades.get(2).counterparty()).isEqualTo("HDFC");  // 500K, HDFC
        assertThat(trades.get(3)).isEqualTo(T3);           // 750K
    }

    // ═══ TreeSet: uses Comparable by default ═══
    @Test
    void treeSet_usesComparable() {
        TreeSet<Trade> set = new TreeSet<>();
        set.add(T1); set.add(T2); set.add(T3);
        assertThat(set.first()).isEqualTo(T2);  // TRD-001 (smallest tradeId)
        assertThat(set.last()).isEqualTo(T1);   // TRD-003 (largest)
    }

    // ═══ TreeSet: override with Comparator ═══
    @Test
    void treeSet_withComparator() {
        TreeSet<Trade> byAmount = new TreeSet<>(Comparator.comparing(Trade::amount));
        byAmount.add(T1); byAmount.add(T2); byAmount.add(T3);
        assertThat(byAmount.first().amount()).isEqualByComparingTo("100000");
        assertThat(byAmount.last().amount()).isEqualByComparingTo("750000");
