// ═══ INTERNAL STRUCTURE ═══
public class CopyOnWriteArrayList<E> {
    private transient volatile Object[] array;  // volatile! Visible to all threads.

    public E get(int index) {
        return (E) array[index];  // direct array access — NO lock!
    }

    public boolean add(E e) {
        synchronized (lock) {
            Object[] oldArr = array;
            Object[] newArr = Arrays.copyOf(oldArr, oldArr.length + 1);  // COPY!
            newArr[oldArr.length] = e;
            array = newArr;  // volatile write → visible to all readers
            return true;
        }
    }

    public Iterator<E> iterator() {
        return new COWIterator(array);  // snapshot of current array!
        // Even if array changes after this, iterator sees OLD snapshot.
        // NEVER throws ConcurrentModificationException!
    }
}

// ═══ USE CASE: listener/observer list ═══
CopyOnWriteArrayList<EventListener> listeners = new CopyOnWriteArrayList<>();
// Listeners added/removed rarely (app startup):
listeners.add(new TradeListener());
listeners.add(new AuditListener());
// Listeners iterated constantly (every trade event):
for (EventListener l : listeners) {  // snapshot — safe even if add() concurrent!
    l.onEvent(event);
}

// ═══ WHEN NOT TO USE ═══
// Write-heavy: every add/remove copies entire array!
// 10K elements + 1K adds/sec = 10M element copies/sec → SLOW!
// Use synchronizedList or ConcurrentLinkedDeque instead.
