// ═══ FAIL-FAST: ArrayList, HashMap, HashSet ═══
List<String> list = new ArrayList<>(List.of("A", "B", "C"));
for (String s : list) {
    if (s.equals("B")) list.remove(s);  // CME! Structural modification during iteration!
}
// Internally: iterator checks modCount before every next()
// list.remove() increments modCount → expectedModCount != modCount → CME!

// FIX 1: use iterator.remove()
Iterator<String> it = list.iterator();
while (it.hasNext()) {
    if (it.next().equals("B")) it.remove();  // SAFE! Iterator knows about this removal.
}

// FIX 2: use removeIf (Java 8)
list.removeIf(s -> s.equals("B"));  // SAFE! Internally uses iterator.remove()

// FIX 3: use CopyOnWriteArrayList (concurrent)
CopyOnWriteArrayList<String> cowl = new CopyOnWriteArrayList<>(List.of("A", "B", "C"));
for (String s : cowl) {
    cowl.remove(s);  // NO CME! Iterator works on snapshot.
}

// ═══ FAIL-SAFE: ConcurrentHashMap, CopyOnWriteArrayList ═══
ConcurrentHashMap<String, Integer> chm = new ConcurrentHashMap<>();
chm.put("A", 1); chm.put("B", 2); chm.put("C", 3);
for (var entry : chm.entrySet()) {
    if (entry.getKey().equals("B")) chm.remove("B");  // NO CME!
    // Weakly consistent: may or may not see the removal during this iteration
}

// ═══ modCount MECHANISM ═══
// ArrayList.add() → modCount++
// ArrayList.remove() → modCount++
// Iterator.next() → if (modCount != expectedModCount) throw CME!
// Iterator.remove() → modCount++ AND expectedModCount = modCount → safe!
