            list.add("X");       // modifies LIVE list, not snapshot
            seen.add(s);
        }
        assertThat(seen).containsExactly("A", "B", "C");  // snapshot = original 3
        assertThat(list).hasSize(6);  // 3 original + 3 added during iteration
    }
