// ═══ STRONG vs WEAK reference ═══
// Strong: Object obj = new Object(); → GC CANNOT collect (someone holds it)
// Weak:   WeakReference<Object> weak = new WeakReference<>(obj);
//         obj = null; → GC CAN collect (only weak ref remains)

// ═══ WeakHashMap behavior ═══
WeakHashMap<Object, String> cache = new WeakHashMap<>();
Object key = new Object();
cache.put(key, "metadata");

cache.get(key);    // "metadata" — key is still strongly referenced by 'key' variable
key = null;        // remove strong reference!
System.gc();       // GC may collect the key → entry auto-removed from WeakHashMap!
// cache.size() might be 0 now!

// ═══ WHY String keys DON'T get collected ═══
WeakHashMap<String, String> map = new WeakHashMap<>();
map.put("hello", "world");
// "hello" is a STRING LITERAL → lives in the string pool → STRONG reference exists!
// This entry will NEVER be collected! Use new String("hello") for weak behavior.

// ═══ USE CASES ═══
// 1. ClassLoader metadata cache — when classloader unloads, metadata auto-cleaned
// 2. Thread-local cleanup — when thread dies, associated data auto-cleaned
// 3. Listener/observer maps — when listener object GC'd, entry removed
// 4. Expensive computation cache — cache results, auto-evict when key unused
