class DeepCloner {
    // IdentityHashMap: == and System.identityHashCode(), flat array
    private final Map<Object,Object> visited = new IdentityHashMap<>();

    @SuppressWarnings("unchecked")
    <T> T clone(T src) {
        if (src == null) return null;
        Object seen = visited.get(src);     // identity lookup
        if (seen != null) return (T) seen;  // cycle → reuse clone

        T copy = allocate(src);
        visited.put(src, copy);             // register BEFORE recursing
        for (Field f : fields(src))
            set(copy, f, clone(get(src, f)));// recurse children
        return copy;
    }
    // Two distinct Account objects with equal content are DIFFERENT keys
    // (unlike HashMap which would collapse them via equals()).
}
