// ─── File: src/test/java/com/bank/custom/CustomHashMapTest.java ───
package com.bank.custom;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class CustomHashMapTest {

    // ═══ MINIMAL CUSTOM HASHMAP ═══
    @SuppressWarnings("unchecked")
    static class MyHashMap<K, V> {
        private static final int INITIAL_CAPACITY = 16;
        private static final float LOAD_FACTOR = 0.75f;

        static class Node<K, V> {
            final int hash;
            final K key;
            V value;
            Node<K, V> next;  // chain

            Node(int hash, K key, V value, Node<K, V> next) {
                this.hash = hash; this.key = key; this.value = value; this.next = next;
            }
        }

        private Node<K, V>[] table;
        private int size;

        MyHashMap() { table = new Node[INITIAL_CAPACITY]; }

        private int hash(K key) {
            int h = key == null ? 0 : key.hashCode();
            return h ^ (h >>> 16);  // spread high bits into low bits!
        }

        public V put(K key, V value) {
            if (size >= table.length * LOAD_FACTOR) resize();
            int idx = hash(key) & (table.length - 1);
            for (Node<K, V> n = table[idx]; n != null; n = n.next) {
                if (n.hash == hash(key) && (key == null ? n.key == null : key.equals(n.key))) {
                    V old = n.value;
                    n.value = value;  // replace!
                    return old;
                }
            }
            table[idx] = new Node<>(hash(key), key, value, table[idx]);  // prepend
            size++;
            return null;
        }

        public V get(K key) {
            int idx = hash(key) & (table.length - 1);
            for (Node<K, V> n = table[idx]; n != null; n = n.next) {
                if (n.hash == hash(key) && (key == null ? n.key == null : key.equals(n.key)))
                    return n.value;
            }
            return null;
        }

        public int size() { return size; }

        private void resize() {
            Node<K, V>[] oldTable = table;
            table = new Node[oldTable.length * 2];
            size = 0;
            for (Node<K, V> head : oldTable) {
                for (Node<K, V> n = head; n != null; n = n.next) {
                    put(n.key, n.value);  // rehash all entries!
                }
            }
        }
    }

    @Test
    void putAndGet() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("SAV2001", 75000);
        map.put("CUR3001", 120000);
        assertThat(map.get("SAV2001")).isEqualTo(75000);
        assertThat(map.get("CUR3001")).isEqualTo(120000);
        assertThat(map.get("INVALID")).isNull();
    }

    @Test
    void duplicateKey_replaces() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("SAV2001", 50000);
        Integer old = map.put("SAV2001", 75000);
        assertThat(old).isEqualTo(50000);
        assertThat(map.get("SAV2001")).isEqualTo(75000);
        assertThat(map.size()).isEqualTo(1);
    }

    @Test
    void resize_handlesGrowth() {
        MyHashMap<Integer, Integer> map = new MyHashMap<>();
        for (int i = 0; i < 100; i++) map.put(i, i * 10);
        assertThat(map.size()).isEqualTo(100);
        assertThat(map.get(50)).isEqualTo(500);
        assertThat(map.get(99)).isEqualTo(990);
    }

    @Test
    void collisions_handled() {
        MyHashMap<String, String> map = new MyHashMap<>();
        // Even with collisions, chaining handles them
        for (int i = 0; i < 50; i++) map.put("key" + i, "val" + i);
        for (int i = 0; i < 50; i++) assertThat(map.get("key" + i)).isEqualTo("val" + i);
    }
}
```

