package com.bank.bigdecimal;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class BigDecimalCompareTest {

    @Test
    void equals_checkScale() {
        BigDecimal a = new BigDecimal("1.0");
        BigDecimal b = new BigDecimal("1.00");
        assertThat(a.equals(b)).isFalse();  // different scale!
    }

    @Test
    void compareTo_checksValueOnly() {
        BigDecimal a = new BigDecimal("1.0");
        BigDecimal b = new BigDecimal("1.00");
        assertThat(a.compareTo(b)).isEqualTo(0);  // EQUAL by value!
    }

    @Test
    void hashSet_gotcha() {
        Set<BigDecimal> set = new HashSet<>();
        set.add(new BigDecimal("1.0"));
        set.add(new BigDecimal("1.00"));
        assertThat(set).hasSize(2);  // TWO entries! HashSet uses equals()!

        // FIX: use TreeSet (uses compareTo)
        Set<BigDecimal> treeSet = new TreeSet<>();
        treeSet.add(new BigDecimal("1.0"));
        treeSet.add(new BigDecimal("1.00"));
        assertThat(treeSet).hasSize(1);  // ONE entry! TreeSet uses compareTo()!
    }

    @Test
    void banking_useCompareTo() {
        BigDecimal balance = new BigDecimal("50000.00");
        BigDecimal withdrawal = new BigDecimal("50000.0");
        // ❌ WRONG: if (balance.equals(withdrawal)) → false!
        // ✅ CORRECT:
        assertThat(balance.compareTo(withdrawal)).isEqualTo(0);  // equal!
        assertThat(balance.compareTo(BigDecimal.ZERO)).isGreaterThan(0);  // positive
    }
}
