package com.bank.generics;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class GenericsTest {

    // ═══ Bounded type parameter ═══
    static <T extends Comparable<T>> T max(List<T> list) {
        return list.stream().max(Comparable::compareTo).orElseThrow();
    }

    @Test
    void boundedType_max() {
        assertThat(max(List.of(3, 1, 2))).isEqualTo(3);
        assertThat(max(List.of("C", "A", "B"))).isEqualTo("C");
    }

    // ═══ PECS: extends = producer (read) ═══
    static double sum(List<? extends Number> numbers) {
        return numbers.stream().mapToDouble(Number::doubleValue).sum();
    }

    @Test
    void pecs_extends_producer() {
        assertThat(sum(List.of(1, 2, 3))).isEqualTo(6.0);        // List<Integer>
        assertThat(sum(List.of(1.5, 2.5))).isEqualTo(4.0);       // List<Double>
        // sum accepts List<Integer>, List<Double>, List<Number> — all extend Number!
    }

    // ═══ PECS: super = consumer (write) ═══
    static void addNumbers(List<? super Integer> list) {
        list.add(1); list.add(2); list.add(3);
    }

    @Test
    void pecs_super_consumer() {
        List<Number> numbers = new ArrayList<>();
        addNumbers(numbers);  // List<Number> is ? super Integer ✅
        assertThat(numbers).containsExactly(1, 2, 3);

        List<Object> objects = new ArrayList<>();
        addNumbers(objects);  // List<Object> is ? super Integer ✅
        assertThat(objects).hasSize(3);
    }

    // ═══ Type erasure — generics are compile-time only ═══
    @Test
    void typeErasure() {
        List<String> strings = new ArrayList<>();
        List<Integer> integers = new ArrayList<>();
        // At runtime: both are just ArrayList (type erased!)
        assertThat(strings.getClass()).isEqualTo(integers.getClass());
    }
}
