// ═══ putIfAbsent: EAGER — value always constructed ═══
Map<String, List<String>> map = new HashMap<>();

// The new ArrayList<>() is created EVERY call — even if key exists!
map.putIfAbsent("SAV2001", new ArrayList<>());  // creates list, inserts
map.putIfAbsent("SAV2001", new ArrayList<>());  // creates list, THROWS IT AWAY!
// Two ArrayList objects created, one wasted!

// For expensive operations:
map.putIfAbsent("SAV2001", loadFromDatabase("SAV2001"));
// loadFromDatabase() executes EVERY TIME — even if key already cached!
// 100 calls = 100 DB queries, even though only the first one matters!

// ═══ computeIfAbsent: LAZY — function runs only when absent ═══
map.computeIfAbsent("SAV2001", k -> new ArrayList<>());  // creates list, inserts
map.computeIfAbsent("SAV2001", k -> new ArrayList<>());  // key exists → function NOT called!
// Only ONE ArrayList created!

// For expensive operations:
map.computeIfAbsent("SAV2001", k -> loadFromDatabase(k));
// loadFromDatabase() runs ONLY on first call! Subsequent calls: cached value returned.
// 100 calls = 1 DB query + 99 cache hits!

// ═══ CACHE PATTERN ═══
ConcurrentHashMap<String, AccountDetails> cache = new ConcurrentHashMap<>();
public AccountDetails getAccount(String id) {
    return cache.computeIfAbsent(id, k -> accountRepository.findById(k));
    // First call: DB query → cache. All subsequent: instant cache hit.
    // ATOMIC in ConcurrentHashMap — no race condition!
}

// ═══ RETURN VALUE DIFFERENCE ═══
// putIfAbsent returns: existing value (if present), NULL (if inserted)
// computeIfAbsent returns: existing OR newly computed value (NEVER null if fn returns non-null)

Map<String, List<String>> groups = new HashMap<>();
// putIfAbsent pattern (verbose):
groups.putIfAbsent("SAV2001", new ArrayList<>());
groups.get("SAV2001").add("TRD-001");  // TWO calls!

// computeIfAbsent pattern (one-liner):
groups.computeIfAbsent("SAV2001", k -> new ArrayList<>()).add("TRD-001");
// ONE call! Returns the list directly.
