   interface Map<K,V>
     + putIfAbsent(K k, V v) : V
         // v evaluated by CALLER before call → eager
         if (!containsKey(k)) put(k,v); return get(k);
     + computeIfAbsent(K k, Function<K,V> f) : V
         // f invoked only if key absent → lazy
         if ((v = get(k)) == null) { v = f.apply(k); if(v!=null) put(k,v); }
         return v;

   class AccountCache
     - Map<String,Account> cache = new ConcurrentHashMap<>();
     - AccountRepository repo;
     + Account find(String id):
         return cache.computeIfAbsent(id, repo::findById); // 1 DB hit/key
     + addTxn(String id, Txn t):
         cache.computeIfAbsent(id, k -> new ArrayList<>()).add(t); // chainable
   // CHM: function runs atomically → no duplicate DB loads under contention
