// ═══ WRONG: for-each + remove → CME ═══
List<String> accounts = new ArrayList<>(List.of("SAV2001", "CLOSED-001", "CUR3001"));
for (String acc : accounts) {
    if (acc.startsWith("CLOSED")) accounts.remove(acc);  // CME!
}
// Internally: for-each creates an Iterator.
// list.remove() increments modCount.
// Iterator.next() checks: modCount != expectedModCount → CME!

// ═══ FIX 1: Iterator.remove() ═══
Iterator<String> it = accounts.iterator();
while (it.hasNext()) {
    if (it.next().startsWith("CLOSED")) it.remove();  // safe!
}

// ═══ FIX 2: removeIf (Java 8) — cleanest! ═══
accounts.removeIf(acc -> acc.startsWith("CLOSED"));
// One line! Internally uses iterator.remove(). No CME.

// ═══ FIX 3: collect and remove after ═══
List<String> toRemove = new ArrayList<>();
for (String acc : accounts) {
    if (acc.startsWith("CLOSED")) toRemove.add(acc);
}
accounts.removeAll(toRemove);

// ═══ WHY modCount exists ═══
// ArrayList tracks modCount (modification count).
// Every add/remove increments modCount.
// Iterator remembers expectedModCount at creation.
// Iterator.next() → if modCount != expectedModCount → CME (fail-fast).
// Iterator.remove() → modCount++ AND expectedModCount++ → both in sync → safe!
```

