        List<String> accounts = new ArrayList<>(List.of("SAV2001", "CLOSED-001", "CUR3001"));
        Iterator<String> it = accounts.iterator();
        while (it.hasNext()) {
            if (it.next().startsWith("CLOSED")) it.remove();
        }
        assertThat(accounts).containsExactly("SAV2001", "CUR3001");
