package com.bank.enumcoll;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class EnumSetMapTest {

    enum AccountType { SAVINGS, CURRENT, FIXED_DEPOSIT, RECURRING, NRI }

    // ═══ EnumSet: fast set operations ═══
    @Test
    void enumSet_bitVectorOps() {
        EnumSet<AccountType> domestic = EnumSet.of(
            AccountType.SAVINGS, AccountType.CURRENT, AccountType.FIXED_DEPOSIT);

        assertThat(domestic.contains(AccountType.SAVINGS)).isTrue();
        assertThat(domestic.contains(AccountType.NRI)).isFalse();
        assertThat(domestic).hasSize(3);
    }

    @Test
    void enumSet_factoryMethods() {
        EnumSet<AccountType> all = EnumSet.allOf(AccountType.class);
        assertThat(all).hasSize(5);

        EnumSet<AccountType> none = EnumSet.noneOf(AccountType.class);
        assertThat(none).isEmpty();

        EnumSet<AccountType> range = EnumSet.range(AccountType.SAVINGS, AccountType.FIXED_DEPOSIT);
        assertThat(range).containsExactly(
            AccountType.SAVINGS, AccountType.CURRENT, AccountType.FIXED_DEPOSIT);

        EnumSet<AccountType> complement = EnumSet.complementOf(range);
        assertThat(complement).containsExactly(AccountType.RECURRING, AccountType.NRI);
    }

    // ═══ EnumMap: array-indexed ═══
    @Test
    void enumMap_arrayIndexed() {
        EnumMap<AccountType, Integer> counts = new EnumMap<>(AccountType.class);
        counts.put(AccountType.SAVINGS, 50000);
        counts.put(AccountType.CURRENT, 12000);
        counts.put(AccountType.NRI, 3000);

        assertThat(counts.get(AccountType.SAVINGS)).isEqualTo(50000);
        assertThat(counts.get(AccountType.FIXED_DEPOSIT)).isNull();  // not set
        assertThat(counts).hasSize(3);
    }

    @Test
    void enumMap_maintainsEnumOrder() {
        EnumMap<AccountType, String> map = new EnumMap<>(AccountType.class);
        map.put(AccountType.NRI, "last");
        map.put(AccountType.SAVINGS, "first");
        // Iteration follows ENUM DECLARATION ORDER (not insertion order!):
        assertThat(new ArrayList<>(map.keySet()))
            .containsExactly(AccountType.SAVINGS, AccountType.NRI);
    }

    // ═══ Performance proof ═══
    @Test
    void performance_enumSetVsHashSet() {
        int iterations = 1_000_000;

        // EnumSet:
        EnumSet<AccountType> enumSet = EnumSet.of(AccountType.SAVINGS, AccountType.CURRENT);
        long t1 = System.nanoTime();
        for (int i = 0; i < iterations; i++) enumSet.contains(AccountType.SAVINGS);
        long enumMs = (System.nanoTime() - t1) / 1_000_000;

        // HashSet:
        HashSet<AccountType> hashSet = new HashSet<>(EnumSet.of(AccountType.SAVINGS, AccountType.CURRENT));
        long t2 = System.nanoTime();
        for (int i = 0; i < iterations; i++) hashSet.contains(AccountType.SAVINGS);
        long hashMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("EnumSet: " + enumMs + "ms, HashSet: " + hashMs + "ms");
        // EnumSet typically 2-5x faster!
    }
}
