        assertThat(balances.higherKey(50000)).isEqualTo(100000);  // > 50K (strictly)
    }

    @Test
    void rangeView_backed() {
        NavigableMap<Integer, String> highBalances = balances.tailMap(100000, true);
        assertThat(highBalances).containsKeys(100000, 500000);

        balances.put(200000, "VERY_HIGH");
        assertThat(highBalances).containsKey(200000);  // view reflects change!
    }

    @Test
    void subMap_range() {
        SortedMap<Integer, String> mid = balances.subMap(50000, 500000);
        assertThat(mid.keySet()).containsExactly(50000, 100000);
        // [50000, 500000) — 500000 excluded!
    }

