Spliterator<Integer> s2 = s1.trySplit();  // s2 gets first half, s1 keeps second half
// s2: elements 0-499 (approximately)
// s1: elements 500-999 (approximately)
// Now TWO threads can process s1 and s2 simultaneously!

// ═══ estimateSize and characteristics ═══
Spliterator<String> sp = accounts.spliterator();
sp.estimateSize();       // 3 (known size — SIZED characteristic)
sp.characteristics();    // ORDERED | SIZED | SUBSIZED | IMMUTABLE

// ═══ HOW PARALLEL STREAMS USE SPLITERATOR ═══
accounts.parallelStream()
    .filter(acc -> acc.startsWith("SAV"))
    .forEach(System.out::println);
// Internally:
// 1. accounts.spliterator() → gets Spliterator
// 2. ForkJoinPool calls trySplit() recursively → divides data
// 3. Each chunk processed by a different thread
// 4. Results merged
