// ═══ COMPARISON TABLE ═══
// Operation    Throws Exception         Returns Special Value
// Insert       add(e) → ISE if full     offer(e) → false if full
// Remove       remove() → NSEE if empty poll() → null if empty
// Examine      element() → NSEE if empty peek() → null if empty

Queue<String> queue = new LinkedList<>();

// ═══ THROWING: remove/element on empty → exception ═══
// queue.remove();   → NoSuchElementException!
// queue.element();  → NoSuchElementException!

// ═══ SPECIAL VALUE: poll/peek on empty → null ═══
String polled = queue.poll();   // null (empty, no exception)
String peeked = queue.peek();   // null (empty, no exception)

// ═══ BOUNDED QUEUE: offer vs add ═══
BlockingQueue<String> bounded = new ArrayBlockingQueue<>(2);
bounded.add("TXN-001");     // ✅
bounded.add("TXN-002");     // ✅
// bounded.add("TXN-003");  // IllegalStateException! Queue full!

bounded.offer("TXN-003");   // false (full, no exception)

// ═══ CONSUMER LOOP — always use poll ═══
while (true) {
    String txn = queue.poll();  // null if empty → loop waits
    if (txn == null) break;     // or sleep/continue
    process(txn);
}
