// ═══ ArrayDeque as Stack (LIFO) ═══
Deque<String> stack = new ArrayDeque<>();
stack.push("TXN-001");    // adds to HEAD (top of stack)
stack.push("TXN-002");
stack.push("TXN-003");

stack.peek();              // "TXN-003" — view top without removing. O(1)
stack.pop();               // "TXN-003" — remove from top. O(1). LIFO!
stack.pop();               // "TXN-002"
stack.pop();               // "TXN-001"
// stack.pop();            // NoSuchElementException if empty!

// ═══ WHY NOT Stack class ═══
Stack<String> legacyStack = new Stack<>();
legacyStack.push("A");
legacyStack.push("B");
legacyStack.get(0);        // "A" — random access! Violates LIFO!
// Every method is synchronized — overhead even single-threaded.
// Stack extends Vector (legacy). ArrayDeque is modern, faster, correct.

// ═══ ArrayDeque as Queue (FIFO) ═══
Deque<String> queue = new ArrayDeque<>();
queue.offer("TXN-001");   // adds to TAIL
queue.offer("TXN-002");
queue.poll();              // "TXN-001" — removes from HEAD. FIFO!

// ═══ INTERNAL: circular array ═══
// Object[] elements — circular buffer
// head index points to first element
// tail index points to next empty slot
// push → head moves LEFT (wraps around)
// offer → tail moves RIGHT (wraps around)
// Growth: doubles when full (2x)
// No null elements allowed (null = empty sentinel)
