// ═══ TYPE ERASURE: what the compiler does ═══
// Source:
public class Box<T> {
    private T item;
    public T getItem() { return item; }
    public void setItem(T item) { this.item = item; }
}
// After erasure (bytecode):
public class Box {
    private Object item;         // T → Object
    public Object getItem() { return item; }
    public void setItem(Object item) { this.item = item; }
}

// Source with bound:
public class NumberBox<T extends Number> {
    private T item;
}
// After erasure:
public class NumberBox {
    private Number item;         // T → Number (the bound!)
}

// ═══ CONSEQUENCE 1: new T() illegal ═══
public <T> T create() {
    // return new T();  → COMPILE ERROR! T is erased to Object at runtime.
    // JVM doesn't know what class T is!
}
// Workaround: pass Class<T>
public <T> T create(Class<T> clazz) throws Exception {
    return clazz.getDeclaredConstructor().newInstance();
}

// ═══ CONSEQUENCE 2: instanceof illegal with generics ═══
// if (list instanceof List<String>) → COMPILE ERROR!
// At runtime: List<String> and List<Integer> are both just List.
if (list instanceof List<?>) { }  // ✅ unbounded wildcard is allowed!

// ═══ CONSEQUENCE 3: generic exception types illegal ═══
// class MyException<T> extends Exception { } → COMPILE ERROR!
// catch (T e) → illegal! JVM needs concrete type for catch.

// ═══ CONSEQUENCE 4: bridge methods ═══
interface Comparable<T> {
    int compareTo(T o);
}
class Account implements Comparable<Account> {
    public int compareTo(Account o) { return /*...*/ 0; }
}
// After erasure, Comparable has: int compareTo(Object o)
// Account has: int compareTo(Account o) — DIFFERENT signature!
// Compiler generates BRIDGE METHOD:
// public int compareTo(Object o) { return compareTo((Account) o); }
// This bridge method satisfies the erased interface signature.

