// ═══ List<?> — can't write ═══
public void process(List<?> list) {
    Object first = list.get(0);   // ✅ can read as Object
    // list.add("test");          // ❌ COMPILE ERROR! ? is unknown type!
    // list.add(42);              // ❌ COMPILE ERROR!
    list.add(null);               // ✅ null is the only valid addition (always safe)
}

// ═══ WHY can't you write? ═══
// List<?> could be List<String>, List<Integer>, List<Account>...
// If ? = Integer: list.add("text") would corrupt the list!
// Compiler prevents ALL adds because it can't verify safety.

// ═══ CAPTURE HELPER — workaround ═══
public void swap(List<?> list, int i, int j) {
    // list.set(i, list.get(j));  // ❌ COMPILE ERROR! Can't set ? type!
    swapHelper(list, i, j);       // ✅ delegate to capture helper!
}

private <T> void swapHelper(List<T> list, int i, int j) {
    T temp = list.get(i);         // ✅ T is captured from ?
    list.set(i, list.get(j));     // ✅ set(int, T) works!
    list.set(j, temp);            // ✅
}
// The compiler captures ? as T → inside swapHelper, T is a concrete type.

// ═══ Collections.swap uses this pattern! ═══
// public static void swap(List<?> list, int i, int j) {
//     final List l = list;  // raw type cast (OpenJDK implementation)
//     l.set(i, l.set(j, l.get(i)));
