// ═══ WHY Enum<E extends Enum<E>>? ═══
// java.lang.Enum:
public abstract class Enum<E extends Enum<E>> implements Comparable<E> {
    public final int compareTo(E o) { ... }
    // E = the specific enum type. compareTo accepts ONLY the SAME enum type!
}
// enum TradeStatus { PENDING, SETTLED }
// Compiler generates: class TradeStatus extends Enum<TradeStatus>
// compareTo(TradeStatus o) — can ONLY compare with TradeStatus, not AccountType!

// Without self-bound: compareTo(Enum o) — could compare TradeStatus with AccountType!

// ═══ FLUENT BUILDER PATTERN ═══
abstract class Builder<T extends Builder<T>> {
    String symbol;

    @SuppressWarnings("unchecked")
    T symbol(String symbol) {
        this.symbol = symbol;
        return (T) this;  // return CONCRETE builder type!
    }
}

class TradeBuilder extends Builder<TradeBuilder> {
    int quantity;

    TradeBuilder quantity(int quantity) {
        this.quantity = quantity;
        return this;
    }
}

// Fluent chain works:
TradeBuilder builder = new TradeBuilder()
    .symbol("RELIANCE")   // returns TradeBuilder (not Builder!)
    .quantity(100);        // works! Because symbol() returned TradeBuilder!

// Without recursive generics:
// symbol() would return Builder → quantity() not available on Builder → compile error!

// ═══ COMPARABLE SELF-TYPING ═══
class Account implements Comparable<Account> {
    String id;
    @Override
    public int compareTo(Account other) {
        return this.id.compareTo(other.id);
    }
    // compareTo ONLY accepts Account — not any Object!
}
