// ─── File: src/test/java/com/bank/resize/HashMapResizeTest.java ───
package com.bank.resize;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.HashMap;
import static org.assertj.core.api.Assertions.*;

class HashMapResizeTest {

    private int getCapacity(HashMap<?,?> map) throws Exception {
        Field table = HashMap.class.getDeclaredField("table");
        table.setAccessible(true);
        Object[] arr = (Object[]) table.get(map);
        return arr == null ? 0 : arr.length;
    }

    @Test
    void resize_doublesCapacity() throws Exception {
        HashMap<Integer, Integer> map = new HashMap<>();  // capacity 16
        for (int i = 0; i < 12; i++) map.put(i, i);
        assertThat(getCapacity(map)).isEqualTo(16);       // still 16

        map.put(12, 12);  // 13th entry → size(13) > threshold(12) → RESIZE!
        assertThat(getCapacity(map)).isEqualTo(32);       // doubled!
    }

    @Test
    void powerOfTwo_alwaysMaintained() throws Exception {
        HashMap<Integer, Integer> map = new HashMap<>(10);  // requested 10
        map.put(0, 0);
        assertThat(getCapacity(map)).isEqualTo(16);  // rounded UP to nearest power of 2!
    }

    @Test
    void bitwiseAnd_equivalentToModulo() {
        int capacity = 16;
        int mask = capacity - 1;  // 15 = 0b1111
        for (int hash = 0; hash < 1000; hash++) {
            assertThat(hash & mask).isEqualTo(hash % capacity);
            // Bitwise AND = modulo for power-of-two! But 10x faster!
        }
    }

    @Test
    void resize_entryStaysOrMoves() {
        // After resize from 16 to 32:
        int oldCapacity = 16;
        int hash1 = 3;   // binary: ...0_0011 → bit4=0 → STAYS at index 3
        int hash2 = 19;  // binary: ...1_0011 → bit4=1 → MOVES to 3+16=19

        assertThat(hash1 & oldCapacity).isEqualTo(0);   // stays!
        assertThat(hash2 & oldCapacity).isNotEqualTo(0); // moves!
    }
}
